--liquibase formatted sql

-- Mirrors com.banu.productservice.entity.Product. That class is a plain object behind an
-- in-memory map today, so nothing reads this table yet; the table exists so the schema is
-- version-controlled from the start.
--
-- Formatted SQL rather than XML, so this is H2 syntax and no longer portable the way the
-- XML <createTable> was - GENERATED BY DEFAULT AS IDENTITY in particular. Retarget the
-- module at another database and this file has to be rewritten.
--
-- The --rollback line is mandatory housekeeping here: for SQL changelogs Liquibase cannot
-- infer the inverse statement the way it can for XML changes, so without it
-- `liquibase:rollback` fails on this changeSet.

--changeset stefanbanu:001-create-product-table
CREATE TABLE product (
    id         BIGINT                   GENERATED BY DEFAULT AS IDENTITY,
    name       VARCHAR(255)             NOT NULL,
    price      DECIMAL(19, 2)           NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_product PRIMARY KEY (id)
);
--rollback DROP TABLE product;
